<?php require_once __DIR__.'/../includes/requireLogin.php';require_once __DIR__.'/../includes/csrf.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../services/authService.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('POST required');}requireLogin();requireValidCsrf();[$errors,$name,$email]=validateProfile((string)($_POST['full_name']??''),(string)($_POST['email']??''));try{if($errors)throw new InvalidArgumentException(implode(' ',$errors));updateOwnProfile(openDatabase(),(int)$_SESSION['user_id'],$name,$email);$_SESSION['display_name']=$name;$_SESSION['email']=$email;header('Location: profile.php?updated=1',true,303);exit;}catch(InvalidArgumentException|PDOException $e){http_response_code(422);$m=$e instanceof PDOException?'An account with that email may already exist.':$e->getMessage();require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?><main class="container py-4"><h1>Profile was not updated</h1><div class="alert alert-danger"><?=htmlspecialchars($m,ENT_QUOTES,'UTF-8')?></div><a href="edit-profile.php">Return to edit profile</a></main><?php require __DIR__.'/../includes/footer.php';}
